// satisa_aktar aracı Vapi'de var mı?
const ARAC = {
  "type": "function",
  "function": {
    "name": "satisa_aktar",
    "description": "Müşteri randevu almak yerine satış temsilcisinin kendisini arayıp bilgi vermesini istediğinde (bilgi alayım, detay verin, bilgi gönderin, temsilci arasın) çağır. Müşteri satış ekibine aktarılır ve sırayla bir satış temsilcisine atanır.",
    "parameters": {
      "type": "object",
      "properties": {
        "ad_soyad": {
          "type": "string",
          "description": "Müşterinin adı soyadı, biliniyorsa."
        },
        "ilgilendigi_daire": {
          "type": "string",
          "enum": [
            "1+1",
            "2+1 A Tipi",
            "2+1 Ebeveyn Banyolu",
            "2+1 Bağımsız Mutfaklı",
            "belirsiz"
          ]
        },
        "not": {
          "type": "string",
          "description": "Müşterinin merak ettiği konu, tek cümle."
        }
      },
      "required": []
    }
  },
  "server": {
    "url": "https://xre111.shop/webhook/efas-ntepe-outbound",
    "timeoutSeconds": 20
  }
};
const mevcut = $('Vapi: Araçlar').all().map((i) => i.json).find((t) => t && t.function && t.function.name === 'satisa_aktar');
return [{ json: { var: !!mevcut, id: mevcut ? mevcut.id : '', govde: ARAC } }];

